# ARC task task-2ce467e9
# Rule: Wide grids (cols > rows): 0s between 5s in same row become 8

def transform(grid):
    """Apply transformation rule."""
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                has_5_left = any(grid[r][cc] == 5 for cc in range(c))
                has_5_right = any(grid[r][cc] == 5 for cc in range(c+1, cols))
                if has_5_left and has_5_right:
                    output[r][c] = 8
    return output
